"use client";
import { useState } from "react";
export default function ChatApp() {
  const [messages, setMessages] = useState([{ role: "assistant", content: "Olá! Sou AI com 200 providers." }]);
  const [input, setInput] = useState("");
  const send = () => {
    if (!input.trim()) return;
    setMessages(m => [...m, { role: "user", content: input }, { role: "assistant", content: `Recebi: ${input} — 200 providers disponíveis` }]);
    setInput("");
  };
  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white flex flex-col max-w-2xl mx-auto p-8">
      <h1 className="text-2xl font-bold">Chat App — 200 Providers</h1>
      <div className="flex-1 mt-6 space-y-4 overflow-y-auto">
        {messages.map((msg, i) => (
          <div key={i} className={`p-4 rounded-xl ${msg.role === "user" ? "bg-white text-black ml-12" : "bg-[#11111b] border border-[#1e1e2e] mr-12"}`}>
            {msg.content}
          </div>
        ))}
      </div>
      <div className="mt-6 flex gap-2">
        <input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} placeholder="Digite mensagem..." className="flex-1 px-4 py-3 rounded-xl bg-[#11111b] border border-[#1e1e2e]" />
        <button onClick={send} className="px-6 py-3 rounded-xl bg-white text-black font-bold">Enviar</button>
      </div>
    </div>
  );
}

